  (gen_random_uuid()::text, '9903.01.01', 'Except for products described in headings 9903.01.02, 9903.01.03, 9903.01.04 and 9903.01.05 articles the product of Mexico, as provided for in U.S. note 2(a) to this subchapter', 'The duty provided in the applicable subheading + 25%', 'additive', 25, ARRAY['MX']::text[], ARRAY['9903.01.02', '9903.01.03', '9903.01.04', '9903.01.05']::text[], ARRAY['2(a)']::text[], '2026 Revision 21', 'koala_gains', now(), now()),
  (gen_random_uuid()::text, '9903.01.02', 'Articles the product of Mexico that are donations, by persons subject to the jurisdiction of the United States, of articles, such as food, clothing, and medicine, intended to be used to relieve human suffering, as provided for in U.S. note 2(b) to this subchapter', 'The duty provided in the applicable subheading', 'relief', NULL, ARRAY['MX']::text[], ARRAY[]::text[], ARRAY['2(b)']::text[], '2026 Revision 21', 'koala_gains', now(), now()),
  (gen_random_uuid()::text, '9903.01.03', 'Articles the product of Mexico that are informational materials, including but not limited to, publications, films, posters, phonograph records, photographs, microfilms, microfiche, tapes, compact disks, CD ROMs, artworks, and news wire feeds', 'The duty provided in the applicable subheading', 'relief', NULL, ARRAY['MX']::text[], ARRAY[]::text[], ARRAY[]::text[], '2026 Revision 21', 'koala_gains', now(), now()),
  (gen_random_uuid()::text, '9903.01.04', 'Articles that are entered free of duty under the terms of general note 11 to the HTSUS, including any treatment set forth in subchapter XXIII of chapter 98 and subchapter XXII of chapter 99 of the HTS, as related to the USMCA', 'No change', 'relief', NULL, ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '2026 Revision 21', 'koala_gains', now(), now()),
