-- Tariff calculator data — HTS 2026 Revision 21
--
-- Source:    https://www.usitc.gov/sites/default/files/tata/hts/hts_2026_revision_21_json.json
-- Generated: 2026-10-09T17:44:43.421Z by src/scripts/tariff-calculator/build-data-sql.ts
-- Inputs:    src/tariff-data/calculator/ch99-headings.json (637 headings, generated 2026-10-09T17:42:04.191Z)
--            src/tariff-data/calculator/measures.json (87 measures, HTS 2026 Revision 21, reviewed 2026-10-09)
--            HTS JSON base rates (29861 numbered rows) from https://www.usitc.gov/sites/default/files/tata/hts/hts_2026_revision_21_json.json
--
-- What it does (one transaction): replaces every koala_gains row of tariff_chapter99_headings and
-- tariff_measures, updates hts_codes rates/units that differ from the edition, then SELECTs counts.
-- Safe to re-run. Never run it by hand against production:
--   1. Review this file in the PR and merge (Prisma migrations apply during the deploy).
--   2. GitHub Actions → "insights-ui: apply data SQL" → sql_file=prisma/data-sql/tariff-calculator/20261009-2026-revision-21.sql, dry_run=true
--      (runs everything, prints the counts, then ROLLBACK).
--   3. Re-run with dry_run=false to COMMIT.
-- See docs/insights-ui/tariffs/calculator-data-refresh.md.

BEGIN;

-- ---------------------------------------------------------------------------
-- tariff_chapter99_headings (637 rows)
-- ---------------------------------------------------------------------------
DELETE FROM tariff_chapter99_headings WHERE space_id = 'koala_gains';


-- ---------------------------------------------------------------------------
-- tariff_measures (87 rows)
-- ---------------------------------------------------------------------------
DELETE FROM tariff_measures WHERE space_id = 'koala_gains';


-- ---------------------------------------------------------------------------
-- hts_codes base rates + units → 2026 Revision 21 (29861 numbered HTS rows; only differing rows change)
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE tmp_hts_base_rates (
  hts_number TEXT PRIMARY KEY,
  general_rate_of_duty TEXT,
  special_rate_of_duty TEXT,
  column2_rate_of_duty TEXT,
  unit_of_quantity TEXT[] NOT NULL
) ON COMMIT DROP;


WITH updated AS (
  UPDATE hts_codes h
     SET general_rate_of_duty = t.general_rate_of_duty,
         special_rate_of_duty = t.special_rate_of_duty,
         column2_rate_of_duty = t.column2_rate_of_duty,
         unit_of_quantity     = t.unit_of_quantity,
         updated_at           = now()
    FROM tmp_hts_base_rates t
   WHERE h.space_id = 'koala_gains'
     AND h.hts_number = t.hts_number
     AND (h.general_rate_of_duty IS DISTINCT FROM t.general_rate_of_duty
       OR h.special_rate_of_duty IS DISTINCT FROM t.special_rate_of_duty
       OR h.column2_rate_of_duty IS DISTINCT FROM t.column2_rate_of_duty
       OR h.unit_of_quantity IS DISTINCT FROM t.unit_of_quantity)
  RETURNING h.hts_number
)
SELECT 'hts_codes rows updated to 2026 Revision 21' AS step, count(*) AS rows FROM updated;

-- Edition rows that hts_codes does not have (new lines, or chapters never ingested) — reported, not inserted.
SELECT 'HTS rows not in hts_codes' AS step, count(*) AS rows
  FROM tmp_hts_base_rates t
 WHERE NOT EXISTS (SELECT 1 FROM hts_codes h WHERE h.space_id = 'koala_gains' AND h.hts_number = t.hts_number);

-- hts_codes lines the edition no longer has (deleted/renumbered) — reported, not deleted.
SELECT 'hts_codes rows not in this edition' AS step, count(*) AS rows
  FROM hts_codes h
 WHERE h.space_id = 'koala_gains' AND h.hts_number IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM tmp_hts_base_rates t WHERE t.hts_number = h.hts_number);

-- ---------------------------------------------------------------------------
-- Counts (expected: 637 headings, 87 measures)
-- ---------------------------------------------------------------------------
SELECT 'tariff_chapter99_headings' AS table_name, count(*) AS rows FROM tariff_chapter99_headings WHERE space_id = 'koala_gains'
UNION ALL SELECT 'tariff_measures', count(*) FROM tariff_measures WHERE space_id = 'koala_gains';

COMMIT;
